using Corvus.Text.Json;
using Corvus.Text.Json.Internal;
using System.Collections.Concurrent;
using System.Net.Http.Headers;
using System.Reflection;
using System.Text;
using Unfucked.HTTP.Config;

namespace Unfucked.HTTP.Serialization;

/// <summary>
/// <para>JSON deserializer using <c>Corvus.JsonSchema</c>. Particularly useful for mapping JSON responses to C# objects which are autogenerated from a JSON Schema (using either the command line or Source Generator). This does not deserialize the schema itself.</para>
/// <para>This class requires the <see href="https://www.nuget.org/packages/Corvus.Text.Json">Corvus.Text.Json</see> NuGet to be explicitly depended upon, because it is not a public dependency of the <c>Unfucked.HTTP</c> package; otherwise it will throw a <see cref="TypeInitializationException"/> when you load it.</para>
/// </summary>
/// <seealso cref="JsonBodyReader"/>
public sealed class ParsedJsonDocumentBodyReader: AbstractMessageBodyReader {

    private static readonly Lazy<ConcurrentDictionary<Type, MethodInfo?>> PARSERS = new(LazyThreadSafetyMode.PublicationOnly);

    /// <inheritdoc />
    public override bool CanRead<T>(MediaTypeHeaderValue? contentType) =>
        PARSERS.Value.GetOrAdd(typeof(T), type => typeof(IJsonElement<>).MakeGenericType(typeof(T)).IsAssignableFrom(type)
            ? typeof(ParsedJsonDocument<>).MakeGenericType(type).GetMethod("ParseAsync", BindingFlags.Public | BindingFlags.Static, null,
                [typeof(Stream), typeof(JsonDocumentOptions), typeof(CancellationToken)], null)
            : null) != null;

    /// <inheritdoc />
    public override async Task<T> Read<T>(HttpResponseMessage response, Encoding? responseEncoding, Configurable? clientConfig, CancellationToken cancellationToken) {
        Stream  responseBody       = await GetBodyStream(response, cancellationToken); // parser assumes and requires response body encoding to be UTF-8
        dynamic parsedJsonDocument = await (dynamic) PARSERS.Value[typeof(T)]!.Invoke(null, [responseBody, default(JsonDocumentOptions), cancellationToken])!;
        return parsedJsonDocument.RootElement;
    }

}